"""Renders the final customvalues.yaml (with provenance comments) and
SUMMARY.md from a BuildOutput.
"""

from __future__ import annotations

import io
from pathlib import Path

from ruamel.yaml import YAML
from ruamel.yaml.comments import CommentedMap

from jfvb.answers import Answers
from jfvb.builder import BuildOutput, Contribution
from jfvb.rules.base import PHASE_ORDER
from jfvb.runbook import PHASE_TITLES

HEADER = """\
# customvalues.yaml -- generated by jfvb (JFrog Platform Values Builder)
#
# This file is meant to be applied on top of the jfrog-platform chart
# defaults ONLY -- no other -f files are required for sizing or feature
# toggles, everything below is already merged. See RUNBOOK.md for the
# exact helm install/upgrade command (it may still need `-f
# openshift-values.yaml` layered last for OpenShift targets) and for
# copy-pasteable setup commands (keys, DB secrets, certificates, etc).
#
# See SUMMARY.md for the full rationale/warnings behind every section.
"""

# `global` applies to every product and is usually what a reviewer wants to
# check first (registry/pull secrets, DB host, master/join key refs), so
# it's always rendered first. The rest follow a fixed, predictable order;
# any key not listed here (future rule modules, unexpected chart sections)
# is appended afterwards in whatever order it was produced.
TOP_LEVEL_KEY_ORDER = [
    "global",
    "artifactory",
    "xray",
    "distribution",
    "catalog",
    "worker",
    "bridge",
    "rabbitmq",
    "postgresql",
]


def _ordered_keys(values: dict) -> list[str]:
    ordered = [key for key in TOP_LEVEL_KEY_ORDER if key in values]
    remaining = [key for key in values if key not in TOP_LEVEL_KEY_ORDER]
    return ordered + remaining


def _runbook_reference(contribution: Contribution) -> str:
    """A short "→ RUNBOOK.md § ..." pointer at the exact section(s) with
    the copy-pasteable commands for whatever this rule flagged, so a
    warning/note is never just a description -- there's always a nearby
    pointer to the fix, and often the section already has the command
    pre-filled with the answers you gave.
    """

    phases_seen: list[str] = []
    for step in contribution.steps:
        if step.phase not in phases_seen:
            phases_seen.append(step.phase)
    if not phases_seen:
        return ""
    phases_seen.sort(key=PHASE_ORDER.index)
    sections = ", ".join(f"§ {PHASE_TITLES[phase]}" for phase in phases_seen)
    return f"RUNBOOK.md {sections}"


def _top_level_provenance(build: BuildOutput) -> dict[str, list[str]]:
    provenance: dict[str, list[str]] = {}
    for contribution in build.contributions:
        for key in contribution.keys:
            provenance.setdefault(key, [])
            if contribution.rule_name not in provenance[key]:
                provenance[key].append(contribution.rule_name)
    return provenance


def render_values_yaml(build: BuildOutput) -> str:
    yaml = YAML()
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.width = 100

    ordered_items = [(key, build.values[key]) for key in _ordered_keys(build.values)]
    top = CommentedMap(ordered_items)
    provenance = _top_level_provenance(build)
    for key in top:
        rules = provenance.get(key, [])
        if rules:
            top.yaml_set_comment_before_after_key(
                key, before=f"--- set by: {', '.join(rules)} ---"
            )

    buffer = io.StringIO()
    yaml.dump(top, buffer)
    return HEADER + "\n" + buffer.getvalue()


def render_summary_md(answers: Answers, build: BuildOutput, chart_version: str | None) -> str:
    lines: list[str] = []
    lines.append("# jfvb build summary")
    lines.append("")
    lines.append(f"- Chart version: `{chart_version or 'latest'}`")
    lines.append(f"- Release/namespace: `{answers.release_name}` / `{answers.namespace}`")
    lines.append(f"- Sizing tier: `{answers.size_tier.value}`")
    lines.append(f"- Worker nodes reported: {answers.worker_node_count}")

    products = answers.products
    enabled = [
        name
        for name, flag in [
            ("Artifactory", products.artifactory),
            ("Xray", products.xray),
            ("Distribution", products.distribution),
            ("Catalog", products.catalog),
            ("Workers", products.workers),
            ("JAS", products.jas),
            ("Curation", products.curation),
            ("SBOM", products.sbom),
            ("Bridge", products.bridge),
            ("AppTrust", products.apptrust),
            ("Mission Control", products.mission_control),
            ("Federation", products.federation),
        ]
        if flag
    ]
    lines.append(f"- Products enabled: {', '.join(enabled)}")
    lines.append(f"- Database mode: `{answers.database.mode.value}`")
    lines.append(f"- Filestore: `{answers.filestore.type.value}`")
    lines.append(f"- Air-gapped: {answers.airgapped}")
    lines.append(f"- OpenShift: {answers.openshift}")
    lines.append("")

    contributions_by_rule = {c.rule_name: c for c in build.contributions}

    warnings = build.warnings
    if warnings:
        lines.append("## Warnings -- review before installing")
        lines.append("")
        for rule, note in warnings:
            lines.append(f"- **[{rule}]** {note}")
            ref = _runbook_reference(contributions_by_rule[rule])
            if ref:
                lines.append(f"  - → Fix it in {ref}")
        lines.append("")

    lines.append("## Rationale / notes, by section")
    lines.append("")
    for contribution in build.contributions:
        if not contribution.notes:
            continue
        lines.append(f"### {contribution.rule_name}")
        lines.append("")
        ref = _runbook_reference(contribution)
        if ref:
            lines.append(f"*Commands for this section: {ref}*")
            lines.append("")
        for note in contribution.notes:
            if note.startswith("WARNING"):
                continue
            lines.append(f"- {note}")
        lines.append("")

    lines.append(
        "See RUNBOOK.md for the ordered, copy-pasteable commands to act on "
        "all of the above (keys, database, certificates, filestore, "
        "install, verification)."
    )
    return "\n".join(lines) + "\n"


def write_outputs(
    answers: Answers,
    build: BuildOutput,
    output_dir: Path,
    chart_version: str | None,
) -> dict[str, Path]:
    output_dir.mkdir(parents=True, exist_ok=True)
    values_path = output_dir / "customvalues.yaml"
    summary_path = output_dir / "SUMMARY.md"

    values_path.write_text(render_values_yaml(build), encoding="utf-8")
    summary_path.write_text(
        render_summary_md(answers, build, chart_version), encoding="utf-8"
    )
    return {"values": values_path, "summary": summary_path}
